sys_script_include.script:
var DisputeUtils = Class.create();
DisputeUtils.prototype = {
    initialize: function() {
    },

	getGroupMembers: function(groupSysId) {
		gs.info("i mehre");

        if (!groupSysId)
            return '';

        var users = [];
        var grMember = new GlideRecordSecure('sys_user_grmember');
        grMember.addQuery('group', groupSysId);
        grMember.query();
		gs.info("Query "+grMember.getEncodedQuery());

        while (grMember.next()) {
            users.push(grMember.user.toString());
        }

		// if(users.length>0)
        // return 'sys_idIN' + users.join(',');
		// else
		// return 'sys_idIN';

    },

    type: 'DisputeUtils'
};
